# PTX source for RMSNorm (fp16 input/output, fp32 accumulation) on SM80
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry rmsnorm_kernel(
    .param .u64   inp_ptr,
    .param .u64   out_ptr,
    .param .u32   batch,
    .param .u32   num_feat,
    .param .u32   dim1,
    .param .u32   dim2,
    .param .f32   eps
)
{
    // ----------------------------
    // Load parameters
    // ----------------------------
    .reg .u64   %in_ptr, %out_ptr;
    .reg .u32   %batch, %num_feat, %dim1, %dim2;
    .reg .f32   %eps_f32;
    ld.param.u64    %in_ptr,    [inp_ptr];
    ld.param.u64    %out_ptr,   [out_ptr];
    ld.param.u32    %batch,     [batch];
    ld.param.u32    %num_feat,  [num_feat];
    ld.param.u32    %dim1,      [dim1];
    ld.param.u32    %dim2,      [dim2];
    ld.param.f32    %eps_f32,   [eps];

    // ----------------------------
    // Compute global linear index for (b, i, j)
    // ----------------------------
    .reg .u32   %tid, %blockDim, %gridDim, %global_idx;
    mov.u32     %tid,        %tid.x;
    mov.u32     %blockDim,   %ctaid.x;
    mul.lo.u32  %global_idx, %blockDim, %ntid.x;
    add.u32     %global_idx, %global_idx, %tid;

    // total locations = batch * dim1 * dim2
    .reg .u32   %total;
    mul.lo.u32  %total, %batch, %dim1;
    mul.lo.u32  %total, %total, %dim2;

    // if out of range, exit
    setp.ge.u32 %p0, %global_idx, %total;
    @%p0        ret;

    // ----------------------------
    // Decompose global index into b, i, j
    // ----------------------------
    .reg .u32   %stride_batch, %b, %rem, %i, %j, %tmp;
    mul.lo.u32  %stride_batch, %dim1, %dim2;               // dim1*dim2

    // b = global_idx / stride_batch
    div.u32     %b, %global_idx, %stride_batch;
    // rem = global_idx - b*stride_batch
    mul.lo.u32  %tmp, %b, %stride_batch;
    sub.u32     %rem, %global_idx, %tmp;

    // i = rem / dim2
    div.u32     %i, %rem, %dim2;
    // j = rem - i*dim2
    mul.lo.u32  %tmp, %i, %dim2;
    sub.u32     %j, %rem, %tmp;

    // ----------------------------
    // Compute base byte offset for this (b,i,j) across feature dimension
    // offset = (( (b*dim1 + i)*dim2 + j) * num_feat) * 2
    // ----------------------------
    .reg .u64   %base_off;
    mul.lo.u32  %tmp, %b, %dim1;          // b*dim1
    add.u32     %tmp, %tmp, %i;          // b*dim1 + i
    mul.lo.u32  %tmp, %tmp, %dim2;       // *dim2
    add.u32     %tmp, %tmp, %j;          // +j
    mul.lo.u32  %tmp, %tmp, %num_feat;   // *num_feat
    cvt.u64.u32 %base_off, %tmp;        // to 64‑bit
    shl.b64     %base_off, %base_off, 1; // *2 (sizeof(half))

    // ----------------------------
    // First pass: compute sum of squares over feature dimension
    // ----------------------------
    .reg .f32   %sum_sq, %val_f32;
    .reg .f16   %val_f16;
    .reg .u32   %c;
    mov.f32     %sum_sq, 0f00000000;    // 0.0f
    xor.b32     %c, %c, %c;            // c = 0

LOOP_SUM:
    setp.ge.u32 %p1, %c, %num_feat;
    @%p1        bra END_SUM;

    // load half
    .reg .u64   %addr_in;
    mad.b64     %addr_in, %c, 2, %base_off; // c*2 + base
    ld.global.nc.f16 %val_f16, [%in_ptr + %addr_in];
    cvt.f32.f16 %val_f32, %val_f16;
    // sum_sq += val_f32 * val_f32
    mul.f32     %val_f32, %val_f32, %val_f32;
    add.f32     %sum_sq, %sum_sq, %val_f32;

    add.u32     %c, %c, 1;
    bra         LOOP_SUM;
END_SUM:

    // mean = sum_sq / num_feat
    .reg .f32   %mean, %rms;
    cvt.f32.u32 %val_f32, %num_feat;
    div.f32     %mean, %sum_sq, %val_f32;
    add.f32     %mean, %mean, %eps_f32;
    sqrt.f32    %rms, %mean;          // rms = sqrt(mean + eps)

    // ----------------------------
    // Second pass: write normalized values
    // ----------------------------
    xor.b32     %c, %c, %c;            // reset c = 0
LOOP_WRITE:
    setp.ge.u32 %p2, %c, %num_feat;
    @%p2        bra END_WRITE;

    // load original half
    .reg .u64   %addr_in2, %addr_out;
    mad.b64     %addr_in2, %c, 2, %base_off;
    ld.global.nc.f16 %val_f16, [%in_ptr + %addr_in2];
    cvt.f32.f16 %val_f32, %val_f16;
    // normalize
    div.f32     %val_f32, %val_f32, %rms;
    // convert back to half
    cvt.f16.f32 %val_f16, %val_f32;
    // store
    mad.b64     %addr_out, %c, 2, %base_off;
    st.global.f16 [%out_ptr + %addr_out], %val_f16;

    add.u32     %c, %c, 1;
    bra         LOOP_WRITE;
END_WRITE:
    ret;
}
'''
# --------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# --------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew:
    def __init__(self, num_features: int, eps: float = 1e-5):
        self.num_features = num_features
        self.eps = float(eps)
        # Load the PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies RMS Normalization using the custom PTX kernel.
        Input and output are fp16 tensors.
        """
        assert x.dtype == torch.float16, "Input must be float16"
        out = torch.empty_like(x)

        batch, _, dim1, dim2 = x.shape
        # one thread per (batch, dim1, dim2) location
        threads_per_block = 256
        total_locs = batch * dim1 * dim2
        grid_x = (total_locs + threads_per_block - 1) // threads_per_block

        # Build argument list for the kernel
        args = [
            x.data_ptr(),
            out.data_ptr(),
            batch,
            self.num_features,
            dim1,
            dim2,
            self.eps,
        ]

        # Launch the kernel
        ptx_launch(
            self.module,
            "rmsnorm_kernel",
            (grid_x, 1, 1),               # grid dimensions
            (threads_per_block, 1, 1),    # block dimensions
            args
        )
        return out
